// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.coreimport timber.log.Timberimport android.app.ActivityManagerimport android.content.Contextimport android.os.Buildimport java.io.File/** * NOUS — Device Capability Detector (Module 6 v4 — Step 6.1, CRITICAL). * * Detects the device's hardware capabilities at runtime to drive the 3-backend * compilation matrix (per strategy v4 §"Critical Engineering Fix 1"): * *  - **SoC vendor** — Qualcomm (QNN), MediaTek (NeuroPilot), Other (XNNPACK) *  - **NPU availability** — yes / no (MediaTek Helio G85 has no NPU, G99 does) *  - **RAM tier** — High (6GB+) / Mid (4GB) / Low (3GB) / Ultra (2GB) * * ## Why this matters * * v3 blindly assumed QNN delegate worked everywhere. On MediaTek Helio G85/G99 * (the actual target $100 hardware), QNN doesn't exist — falling back to * generic TFLite NNAPI causes Omni-SLM layers to fall back to CPU, blowing up * 450ms latency target to 4-6 seconds. * * v4 detects the SoC at runtime and selects the correct backend: * * | Device | SoC | Backend | Omni-SLM Latency | * |--------|-----|---------|------------------| * | Pixel 8 Pro | SD 8 Gen 3 | QNN | 350 ms ✅ | * | Redmi Note 13 Pro | SD 7 Gen 1 | QNN | 550 ms ✅ | * | Realme Narzo 60 | Dimensity 7050 | NeuroPilot | 480 ms ✅ | * | Redmi 12 | Helio G99 | NeuroPilot + OpenCL | 650 ms ✅ | * | Redmi 12C | Helio G85 | XNNPACK + OpenCL | 1100 ms ⚠️ | * | Ultra-low (2GB) | Any | Disabled (v2 fallback) | N/A | * * ## Testability * * The detector reads from a [HardwareProbe] interface. Production injects * [AndroidHardwareProbe]; tests inject [FakeHardwareProbe] to simulate any * device tier without needing real hardware. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Critical Engineering Fix 1: MediaTek NPU Gap</a> */class DeviceCapabilityDetector(    private val probe: HardwareProbe,) {    /**     * Detect the device's SoC vendor.     *     * Detection logic (in priority order):     *  1. Read `/proc/cpuinfo` for "Hardware" or "Processor" line.     *  2. Check `Build.HARDWARE` (e.g., "qcom", "mt6739", "exynos").     *  3. Check `Build.BOARD` for vendor hints.     *     * @return the detected SoC vendor, or [SocVendor.OTHER] if unknown.     */    fun detectSocVendor(): SocVendor {        val cpuInfo = probe.readCpuInfo()        val hardware = probe.readBuildHardware().lowercase()        val board = probe.readBuildBoard().lowercase()        return when {            // Qualcomm Snapdragon — "qcom", "qualcomm", "msm8998", "sdm660"            cpuInfo.contains("qualcomm", ignoreCase = true) ||            cpuInfo.contains("qcom", ignoreCase = true) ||            hardware.contains("qcom") ||            board.contains("qcom") ||            board.startsWith("msm") ||            board.startsWith("sdm") ||            board.startsWith("sm8") -> SocVendor.QUALCOMM            // MediaTek — "mt6739", "mt6768", "helio", "dimensity", "mtk"            cpuInfo.contains("mediatek", ignoreCase = true) ||            cpuInfo.contains("mtk", ignoreCase = true) ||            hardware.contains("mt") ||            board.startsWith("mt") ||            board.contains("helio") ||            board.contains("dimensity") -> SocVendor.MEDIATEK            // Samsung Exynos            cpuInfo.contains("samsung", ignoreCase = true) ||            hardware.contains("exynos") ||            board.startsWith("exynos") -> SocVendor.SAMSUNG_EXYNOS            // Google Tensor            hardware.contains("tensor") ||            board.contains("tensor") -> SocVendor.GOOGLE_TENSOR            // Unisoc (popular in ultra-low-end India phones)            cpuInfo.contains("unisoc", ignoreCase = true) ||            hardware.contains("unisoc") ||            board.startsWith("sc") -> SocVendor.UNISOC            else -> {                Timber.tag(TAG).w("Unknown SoC vendor. cpuInfo=${cpuInfo.take(100)}, hardware=$hardware, board=$board")                SocVendor.OTHER            }        }    }    /**     * Detect NPU availability.     *     * NPU presence is inferred from SoC vendor + model:     *  - Qualcomm Snapdragon 7 Gen 1+ → NPU (Hexagon DSP HVX)     *  - MediaTek Dimensity 700+ / Helio G99+ → NPU (APU)     *  - MediaTek Helio G85 and below → NO NPU (CPU + GPU only)     *     * For accurate detection, we also check for `/dev/vendor/npu` or     * `/sys/class/npu/` (vendor-specific paths).     *     * @return true if NPU is available, false otherwise.     */    fun detectNpuAvailability(): Boolean {        val soc = detectSocVendor()        // Check vendor-specific NPU device paths.        if (probe.fileExists("/dev/vendor/npu") ||            probe.fileExists("/dev/npu") ||            probe.fileExists("/sys/class/npu/")        ) {            return true        }        // Fallback: infer from SoC vendor + board.        val board = probe.readBuildBoard().lowercase()        return when (soc) {            SocVendor.QUALCOMM -> {                // Snapdragon 7 Gen 1+ (sm7475, sm7450) and 8 series have NPU.                // 6 series and below: no NPU.                board.startsWith("sm7") || board.startsWith("sm8") || board.startsWith("sm6") && !board.startsWith("sm6150")            }            SocVendor.MEDIATEK -> {                // Dimensity 700+ (mt6877, mt6833, etc.) and Helio G99 (mt6789) have NPU.                // Helio G85 (mt6762z) does NOT have NPU.                val npuBoards = listOf(                    "mt68",   // Dimensity series                    "mt6789", // Helio G99                    "mt6785", // Helio G90T                    "mt6853", // Dimensity 720                )                npuBoards.any { board.startsWith(it) }            }            SocVendor.SAMSUNG_EXYNOS -> {                // Exynos 1380+ has NPU; older ones don't.                board.startsWith("s5e88") || board.startsWith("s5e99")            }            SocVendor.GOOGLE_TENSOR -> true // All Tensor chips have NPU            SocVendor.UNISOC -> false // Unisoc Tiger T618+ has NPU; we conservatively say no            SocVendor.OTHER -> false        }    }    /**     * Detect the device's RAM tier.     *     * Used to decide:     *  - High (6GB+): Omni-SLM INT4 (580 MB) + full KV cache (140 MB) + 10s ring buffer     *  - Mid (4GB):   Omni-SLM INT4 (580 MB) + reduced KV cache (80 MB) + 10s ring buffer     *  - Low (3GB):   Omni-SLM INT2 (290 MB) + tiny KV cache (40 MB) + 5s ring buffer     *  - Ultra (2GB): Omni-SLM disabled → v2 fallback (MiniLM + BERT-tiny)     *     * @return the RAM tier.     */    fun detectRamTier(): RamTier {        val totalRamMb = probe.totalRamMb()        return when {            totalRamMb >= 6_144 -> RamTier.HIGH       // 6 GB+            totalRamMb >= 3_840 -> RamTier.MID        // 4 GB (3840 MB usable)            totalRamMb >= 2_880 -> RamTier.LOW        // 3 GB (2880 MB usable)            else -> RamTier.ULTRA                     // < 3 GB        }    }    /**     * Compute the full device capability snapshot.     *     * This is what [ModelManager] uses to select the correct backend + quantization.     */    fun detect(): DeviceCapability {        val soc = detectSocVendor()        val hasNpu = detectNpuAvailability()        val ramTier = detectRamTier()        Timber.tag(TAG).i("Device capability: soc=$soc, npu=$hasNpu, ramTier=$ramTier")        return DeviceCapability(            socVendor = soc,            hasNpu = hasNpu,            ramTier = ramTier,            totalRamMb = probe.totalRamMb(),            board = probe.readBuildBoard(),            hardware = probe.readBuildHardware(),        )    }    private companion object {        private const val TAG = "DeviceCapDetector"    }}// ──────────────────────────────────────────────────────────────────────────/** SoC vendor detected on the device. */enum class SocVendor {    QUALCOMM,        // Snapdragon — uses QNN delegate    MEDIATEK,        // Helio / Dimensity — uses NeuroPilot + OpenCL fallback    SAMSUNG_EXYNOS,  // Exynos — uses OpenCL + NNAPI    GOOGLE_TENSOR,   // Pixel — uses EdgeTPU    UNISOC,          // Unisoc Tiger — uses CPU only (XNNPACK)    OTHER,           // Unknown — fall back to XNNPACK CPU}/** RAM tier — drives quantization + KV cache size + ring buffer length. */enum class RamTier {    /** 6 GB+ — full INT4 Omni-SLM (580 MB) + 140 MB KV cache + 10s ring buffer. */    HIGH,    /** 4 GB — full INT4 Omni-SLM (580 MB) + 80 MB KV cache + 10s ring buffer. */    MID,    /** 3 GB — INT2 Omni-SLM (290 MB) + 40 MB KV cache + 5s ring buffer. */    LOW,    /** < 3 GB — Omni-SLM disabled, fall back to v2 stack (MiniLM + BERT-tiny). */    ULTRA,}/** Full device capability snapshot. */data class DeviceCapability(    val socVendor: SocVendor,    val hasNpu: Boolean,    val ramTier: RamTier,    val totalRamMb: Long,    val board: String,    val hardware: String,) {    /** True if this device can run the Omni-SLM at all (vs v2 fallback). */    val supportsOmniSlm: Boolean        get() = ramTier != RamTier.ULTRA    /** True if this device should use INT2 quantization (3 GB RAM tier). */    val requiresInt2Quantization: Boolean        get() = ramTier == RamTier.LOW    /** Maximum number of models that can be loaded simultaneously. */    val maxConcurrentModels: Int        get() = when (ramTier) {            RamTier.HIGH -> 3   // Omni-SLM + SSD + ML Kit OCR            RamTier.MID -> 3            RamTier.LOW -> 2    // Omni-SLM INT2 + SSD (ML Kit lazy)            RamTier.ULTRA -> 1  // Only SSD (Omni-SLM disabled)        }}// ──────────────────────────────────────────────────────────────────────────/** * Hardware probe interface — abstracts Android system APIs for testability. * * Production impl: [AndroidHardwareProbe] reads from real device. * Test impl: [FakeHardwareProbe] returns canned values. */interface HardwareProbe {    /** Read `/proc/cpuinfo` (returns empty string if unavailable). */    fun readCpuInfo(): String    /** Read `Build.HARDWARE` (e.g., "qcom", "mt6739"). */    fun readBuildHardware(): String    /** Read `Build.BOARD` (e.g., "sm8450", "mt6789"). */    fun readBuildBoard(): String    /** Total device RAM in MB (0 if unavailable). */    fun totalRamMb(): Long    /** Check if a file exists at [path] (for NPU device paths). */    fun fileExists(path: String): Boolean}/** * Production [HardwareProbe] — reads from real Android device. * * Uses [Context]'s [ActivityManager.MemoryInfo] for RAM, [Build] for hardware * strings, and [File] for `/proc/cpuinfo` + NPU device paths. */class AndroidHardwareProbe(    private val context: Context,) : HardwareProbe {    override fun readCpuInfo(): String = try {        File("/proc/cpuinfo").readText()    } catch (t: Throwable) {        Timber.tag(TAG).w("Failed to read /proc/cpuinfo", t)        ""    }    override fun readBuildHardware(): String = Build.HARDWARE ?: ""    override fun readBuildBoard(): String = Build.BOARD ?: ""    override fun totalRamMb(): Long = try {        val activityManager = context.getSystemService(Context.ACTIVITY_SERVICE) as? ActivityManager        val memoryInfo = ActivityManager.MemoryInfo()        activityManager?.getMemoryInfo(memoryInfo)        memoryInfo.totalMem / (1024 * 1024)    } catch (t: Throwable) {        Timber.tag(TAG).w("Failed to read total RAM", t)        0L    }    override fun fileExists(path: String): Boolean = File(path).exists()    private companion object {        private const val TAG = "AndroidHardwareProbe"    }}